424	+// newImportProgressReporter wires an agentimport.Progress to user-visible
425	+// output on w for one agent's import run. On an interactive terminal
426	+// (outside ACCESSIBLE mode) it drives an updatable spinner whose message
427	+// tracks "Importing <agentName> sessions... (session i/N · turn j/M)";
428	+// callers must call the returned stop exactly once when the run finishes —
429	+// on both the success and error paths — so no spinner frame is left
430	+// dangling to corrupt whatever prints next. Otherwise (non-TTY, piped, or
431	+// ACCESSIBLE mode) it prints one plain, ANSI-free line per session from
432	+// SessionStart, and stop is a no-op.
433	+func newImportProgressReporter(w io.Writer, agentName string) (progress *agentimport.Progress, stop func(success bool)) {
434	+	if !interactive.IsTerminalWriter(w) || IsAccessibleMode() {
435	+		return &agentimport.Progress{
436	+			SessionStart: func(sessionIndex, sessionTotal int, _, _ string, turnCount int) {
437	+				fmt.Fprintf(w, "Importing %s session %d/%d (%d %s)...\n",
438	+					agentName, sessionIndex+1, sessionTotal, turnCount, pluralize("turn", turnCount))
439	+			},
440	+		}, func(bool) {}
441	+	}
442	+
443	+	update, spinnerStop := startUpdatableSpinner(w, fmt.Sprintf("Importing %s sessions...", agentName))
444	+	var curSession, curSessionTotal, curTurnTotal int
445	+	render := func(turnsDone int) {
446	+		update(fmt.Sprintf("Importing %s sessions... (session %d/%d · turn %d/%d)",
447	+			agentName, curSession, curSessionTotal, turnsDone, curTurnTotal))
448	+	}
449	+	advance := func(_, turnIndex, _ int) {
450	+		render(turnIndex + 1)
451	+	}
452	+	progress = &agentimport.Progress{
453	+		SessionStart: func(sessionIndex, sessionTotal int, _, _ string, turnCount int) {
454	+			curSession, curSessionTotal, curTurnTotal = sessionIndex+1, sessionTotal, turnCount
455	+			render(0)
456	+		},
457	+		// TurnWritten and TurnSkipped share the same advance path: the
458	+		// counter must sweep to turnCount/turnCount regardless of *why* a
459	+		// turn didn't need writing (already imported, or DryRun), otherwise
460	+		// a fully-skipped or dry-run session's completion line would freeze
461	+		// at "turn 0/M".
462	+		TurnWritten: advance,
463	+		TurnSkipped: advance,
464	+	}
465	+	return progress, spinnerStop
466	+}
